create function public.dispatch_curriculum_plan_exam(p_plan_id uuid, p_item_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  p public.institution_curriculum_plans%rowtype;
  i public.curriculum_plan_template_items%rowtype;
  v_assignment uuid; v_students uuid[]; v_course uuid; v_anchor integer; v_start timestamptz;
begin
  select * into p from public.institution_curriculum_plans where id = p_plan_id for update;
  if auth.uid() is null or not coalesce(private.can_manage_curriculum_plan(p_plan_id),false)
    or p.tenant_id is distinct from private.current_tenant_id() then raise exception '无权布置此计划的考试'; end if;
  if p.status not in ('published','active') then raise exception '只有有效机构计划可以布置考试'; end if;
  select * into i from public.curriculum_plan_template_items where id = p_item_id and template_id = p.template_id;
  if i.id is null or i.source_type <> 'assessment_paper' then raise exception '计划项目未绑定标准考试卷'; end if;
  select array_agg(s.student_id) into v_students from public.institution_curriculum_plan_students s where s.plan_id = p.id;
  if coalesce(cardinality(v_students),0) = 0 then raise exception '请先向计划分配学生'; end if;
  if exists (select 1 from unnest(v_students) s(id) where not exists (
    select 1 from public.student_app_enrollments e where e.student_id = s.id and e.tenant_id = p.tenant_id
      and e.app_id = p.student_app_id and e.status = 'active' and e.starts_at <= now() and (e.ends_at is null or e.ends_at > now())
  )) then raise exception '计划中存在未开通或已失效的学生，请先处理学生授权'; end if;
  if public.current_profile_role() = 'teacher' and exists (
    select 1 from unnest(v_students) s(id) where not exists (
      select 1 from public.tenant_student_assignments a where a.tenant_id = p.tenant_id
        and a.student_app_id = p.student_app_id and a.teacher_id = auth.uid() and a.student_id = s.id
    )
  ) then raise exception '老师只能向当前应用中自己负责的学生布置考试'; end if;
  select assignment_id into v_assignment from public.curriculum_plan_assessments where plan_id = p.id and item_id = i.id;
  if v_assignment is not null then return v_assignment; end if;
  select course_id into v_course from public.curriculum_plan_templates where id = p.template_id;
  select min(day_offset * 1440 + start_minute) into v_anchor from public.curriculum_plan_template_items where template_id = p.template_id;
  v_start := p.starts_at + make_interval(mins => i.day_offset * 1440 + i.start_minute - v_anchor);
  if v_start <= now() then raise exception '考试计划时间已经开始，请采用新计划安排未来的考试'; end if;
  v_assignment := public.create_learning_assignment_from_paper_with_unlock(
    i.source_id, v_course, 'selected_students', v_students, v_start,
    v_start + make_interval(mins => i.duration_minutes), coalesce(i.instructions,''),
    false, null, false, 1, false, false, null, null, '{}'::uuid[], null, null, 'highest', null
  );
  insert into public.curriculum_plan_assessments(plan_id,item_id,assignment_id,created_by) values(p.id,i.id,v_assignment,auth.uid());
  return v_assignment;
end $$;
revoke all on function public.dispatch_curriculum_plan_exam(uuid,uuid) from public,anon,authenticated;
grant execute on function public.dispatch_curriculum_plan_exam(uuid,uuid) to authenticated;

-- Appending students must not silently leave them out of an already dispatched exam.
-- Keep this explicit: no silent changes to live examination recipients.
create function private.guard_curriculum_exam_roster() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  perform 1 from public.institution_curriculum_plans where id = new.plan_id for update;
  if exists(select 1 from public.curriculum_plan_assessments where plan_id = new.plan_id)
    and not exists(select 1 from public.institution_curriculum_plan_students where plan_id = new.plan_id and student_id = new.student_id) then
    raise exception '此计划已布置考试；请为新增学生发布单独计划，避免遗漏考试名单';
  end if;
  return new;
end $$;
revoke all on function private.guard_curriculum_exam_roster() from public,anon,authenticated;
create trigger curriculum_exam_roster_guard before insert or update on public.institution_curriculum_plan_students
  for each row execute function private.guard_curriculum_exam_roster();

create function private.guard_curriculum_exam_cancellation() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.status = 'cancelled' and old.status <> 'cancelled' and exists (
    select 1 from public.curriculum_plan_assessments ca join public.learning_assignments a on a.id = ca.assignment_id
      where ca.plan_id = new.id and a.status = 'published'
  ) then raise exception '此计划还有已布置的考试，请先在考试管理中结束考试，再取消计划'; end if;
  return new;
end $$;
revoke all on function private.guard_curriculum_exam_cancellation() from public,anon,authenticated;
create trigger curriculum_exam_cancellation_guard before update on public.institution_curriculum_plans
  for each row execute function private.guard_curriculum_exam_cancellation();

-- Returns only completion facts, never answers, tokens or private grading content.
-- All reads are scoped to current tenant, active app enrollment and teacher relationships.
create function public.get_curriculum_execution(p_plan_ids uuid[]) returns jsonb
language sql stable security definer set search_path = '' as $$
with permitted as (
  select p.*, s.student_id, t.course_id
  from public.institution_curriculum_plans p
  join public.curriculum_plan_templates t on t.id = p.template_id
  join public.institution_curriculum_plan_students s on s.plan_id = p.id and s.tenant_id = p.tenant_id
  join public.student_app_enrollments en on en.tenant_id = p.tenant_id and en.student_id = s.student_id
    and en.app_id = p.student_app_id and en.status = 'active' and en.starts_at <= now() and (en.ends_at is null or en.ends_at > now())
  join public.tenant_memberships m on m.tenant_id = p.tenant_id and m.user_id = s.student_id and m.status = 'active' and m.role = 'student'
  where p.id = any(p_plan_ids) and p.tenant_id = private.current_tenant_id() and auth.uid() is not null
    and p.status in ('published','active','completed')
    and (s.student_id = auth.uid() or (
      private.can_manage_curriculum_plan(p.id)
      and (public.current_profile_role() <> 'teacher' or exists (
        select 1 from public.tenant_student_assignments a where a.tenant_id = p.tenant_id
          and a.student_app_id = p.student_app_id and a.teacher_id = auth.uid() and a.student_id = s.student_id
      ))
    ))
), facts as (
  select p.id plan_id, i.id item_id, p.student_id, i.source_type,
    case i.source_type
      when 'lesson' then coalesce(lp.status = 'completed',false)
      when 'chapter' then ep.completed_at is not null
      when 'chapter_test' then coalesce(ta.passed,false)
      when 'chapter_practice' then pp.completed_at is not null
      when 'specialized_practice' then coalesce(tp.completed,false)
      when 'assessment_paper' then coalesce(sub.submission_state = 'grade_released' and sub.grade_released_at is not null,false)
      else false end completed,
    case i.source_type
      when 'lesson' then coalesce(lp.status <> 'not_started',false)
      when 'chapter' then ep.id is not null
      when 'chapter_test' then coalesce(ta.started,false)
      when 'chapter_practice' then pp.started_at is not null
      when 'specialized_practice' then coalesce(tp.started,false)
      when 'assessment_paper' then sub.id is not null
      else false end started,
    coalesce(sub.submission_state in ('submitted_pending_grading','objective_graded_pending_manual','grading_completed'),false) pending_grading,
    case i.source_type
      when 'lesson' then coalesce(l.is_published,false)
      when 'chapter' then coalesce(ch.is_published,false)
      when 'chapter_test' then coalesce(test.status = 'published',false)
      when 'chapter_practice' then coalesce(u.status in ('published','needs_update'),false)
      when 'specialized_practice' then coalesce(ex.status = 'published',false)
      when 'assessment_paper' then a.id is not null and a.status in ('published','closed')
      else false end available,
    case i.source_type when 'lesson' then lp.progress_percent when 'chapter' then ep.progress_percent
      when 'chapter_practice' then pp.progress_percent else null end progress_percent,
    a.id assignment_id, a.starts_at, a.due_at
  from permitted p join public.curriculum_plan_template_items i on i.template_id = p.template_id
  left join public.lessons l on i.source_type = 'lesson' and l.id = i.source_id and l.course_id = p.course_id
  left join public.lesson_progress lp on lp.lesson_id = l.id and lp.user_id = p.student_id and lp.tenant_id = p.tenant_id
  left join public.course_chapters ch on i.source_type = 'chapter' and ch.id = i.source_id
  left join public.chapter_tests cht on cht.id = ch.chapter_test_id and cht.student_app_id = p.student_app_id
  left join public.course_ebook_progress ep on ep.test_slug = cht.slug and ep.student_id = p.student_id
    and ep.tenant_id = p.tenant_id and ep.student_app_id = p.student_app_id
  left join public.chapter_tests test on i.source_type = 'chapter_test' and test.id = i.source_id and test.student_app_id = p.student_app_id
  left join lateral (select bool_or(at.passed) passed, count(*) > 0 started from public.chapter_test_attempts at
    where at.test_id = test.id and at.student_id = p.student_id and at.tenant_id = p.tenant_id) ta on true
  left join public.chapter_practice_units u on i.source_type = 'chapter_practice' and u.id = i.source_id and u.student_app_id = p.student_app_id
  left join public.student_chapter_practice_progress pp on pp.practice_unit_id = u.id and pp.student_id = p.student_id and pp.tenant_id = p.tenant_id
  left join public.growth_toolbox_exercises ex on i.source_type = 'specialized_practice' and ex.id = i.source_id and ex.student_app_id = p.student_app_id
  left join lateral (select bool_or(s.status = 'completed' and s.completed_at is not null) completed, count(*) > 0 started
    from public.toolbox_practice_sessions s where s.exercise_id = ex.id and s.student_id = p.student_id
      and s.tenant_id = p.tenant_id and s.started_at >= p.starts_at + make_interval(mins =>
        i.day_offset * 1440 + i.start_minute - (select min(pi.day_offset * 1440 + pi.start_minute)
          from public.curriculum_plan_template_items pi where pi.template_id = p.template_id))) tp on true
  left join public.curriculum_plan_assessments ca on ca.plan_id = p.id and ca.item_id = i.id
  left join public.learning_assignments a on a.id = ca.assignment_id and a.tenant_id = p.tenant_id and a.student_app_id = p.student_app_id
    and (a.target_scope = 'all_students' or exists(select 1 from public.learning_assignment_targets target where target.assignment_id = a.id and target.student_id = p.student_id))
  left join lateral (select s.id,s.submission_state,s.grade_released_at from public.learning_submissions s
    where s.assignment_id = a.id and s.student_id = p.student_id and s.tenant_id = p.tenant_id
    order by s.attempt_number desc, s.submitted_at desc limit 1) sub on true
)
select coalesce(jsonb_agg(to_jsonb(facts) - 'source_type' || jsonb_build_object('tracked',source_type <> 'manual')), '[]'::jsonb) from facts;
$$;
revoke all on function public.get_curriculum_execution(uuid[]) from public,anon,authenticated;
grant execute on function public.get_curriculum_execution(uuid[]) to authenticated;

commit;

-- Reissue of historical local-only change 202609080005_completion_policy_management.sql.
-- Not present in the production cutover ledger/schema. See bootstrap orphan decisions.
-- Reviewed for target clone compatibility; existing authorization and grants retained.
begin;
create function public.save_completion_policy_draft(p_id uuid, p_course_id uuid, p_title text, p_requirements jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_app uuid; v_id uuid; v_version integer;
begin
  if auth.uid() is null or not coalesce(private.is_platform_owner(),false) then raise exception '只有平台负责人可以维护结课政策'; end if;
  select c.student_app_id into v_app from public.courses c join public.student_apps a on a.id = c.student_app_id
    where c.id = p_course_id and a.slug = 'korean' and c.content_scope = 'platform';
  if v_app is null or not coalesce(private.completion_policy_requirements_are_valid(p_requirements),false) then raise exception '课程或结课要求无效'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_course_id::text, 19));
  if p_id is not null then
    update public.course_completion_policies set title = p_title, requirements = p_requirements
      where id = p_id and course_id = p_course_id and status = 'draft' returning id into v_id;
    if v_id is null then raise exception '只能修改此课程的草稿政策'; end if;
  else
    select coalesce(max(version),0)+1 into v_version from public.course_completion_policies where course_id = p_course_id;
    insert into public.course_completion_policies(student_app_id,course_id,policy_code,version,title,requirements,created_by)
      values(v_app,p_course_id,'COURSE_' || upper(replace(p_course_id::text,'-','')),v_version,p_title,p_requirements,auth.uid()) returning id into v_id;
  end if;
  return v_id;
end $$;
create function public.publish_completion_policy_draft(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare p public.course_completion_policies%rowtype;
begin
  if auth.uid() is null or not coalesce(private.is_platform_owner(),false) then raise exception '只有平台负责人可以发布结课政策'; end if;
  select * into p from public.course_completion_policies where id = p_id;
  if p.id is null then raise exception '政策不存在'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p.course_id::text,19));
  select * into p from public.course_completion_policies where id = p_id for update;
  if p.status <> 'draft' then raise exception '只能发布草稿政策'; end if;
  -- Replacement is atomic. A validation failure rolls the retirement back too.
  update public.course_completion_policies set status = 'retired' where course_id = p.course_id and status = 'published' and is_default;
  update public.course_completion_policies set status = 'published', is_default = true, effective_from = now(), effective_until = null where id = p.id;
end $$;
create function public.get_completion_refresh_health() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null or not coalesce(private.is_platform_owner(),false) then raise exception '只有平台负责人可以查看刷新任务'; end if;
  return (select jsonb_build_object('pending',count(*) filter(where status = 'pending'),
    'failed',count(*) filter(where status in ('failed','partial_failed')), 'processing',count(*) filter(where status = 'processing'),
    'lastFinishedAt',max(finished_at)) from public.course_completion_refresh_tasks);
end $$;
create function public.retry_failed_completion_refresh() returns integer
language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  if auth.uid() is null or not coalesce(private.is_platform_owner(),false) then raise exception '只有平台负责人可以重试刷新任务'; end if;
  update public.course_completion_refresh_tasks t set status='pending',available_at=now(),worker_token=null,finished_at=null
    where t.id in (select f.id from public.course_completion_refresh_tasks f
      where f.status in ('failed','partial_failed') and not exists(select 1 from public.course_completion_refresh_tasks a
        where a.dedupe_key=f.dedupe_key and a.status in ('pending','processing'))
      order by f.created_at limit 10 for update skip locked);
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function public.save_completion_policy_draft(uuid,uuid,text,jsonb) from public,anon,authenticated;
revoke all on function public.publish_completion_policy_draft(uuid) from public,anon,authenticated;
revoke all on function public.get_completion_refresh_health() from public,anon,authenticated;
grant execute on function public.save_completion_policy_draft(uuid,uuid,text,jsonb) to authenticated;
grant execute on function public.publish_completion_policy_draft(uuid) to authenticated;
grant execute on function public.get_completion_refresh_health() to authenticated;
revoke all on function public.retry_failed_completion_refresh() from public,anon,authenticated;
grant execute on function public.retry_failed_completion_refresh() to authenticated;
commit;

-- R2A: authenticated public content is tenant-bound; raw authoring nodes remain owner-only.
-- Existing owner/standard-question-bank management policies are intentionally preserved.
BEGIN;
CREATE FUNCTION private.can_read_published_textbook(p_textbook_id uuid) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_tenant uuid := private.current_tenant_id();
  v_app uuid;
  v_category uuid;
  v_parent uuid;
  v_depth integer := 0;
  v_seen uuid[] := ARRAY[]::uuid[];
BEGIN
  IF auth.uid() IS NULL OR v_tenant IS NULL THEN RETURN false; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p
    JOIN public.tenant_memberships tm ON tm.user_id=p.id
    JOIN public.tenants t ON t.id=tm.tenant_id
    WHERE p.id=auth.uid() AND p.status='active' AND tm.tenant_id=v_tenant
      AND tm.status='active' AND t.status='active'
      AND tm.role IN ('student','teacher','admin','ceo','tenant_super_admin')
  ) THEN RETURN false; END IF;
  SELECT b.student_app_id,c.category_id INTO v_app,v_category
  FROM public.digital_textbooks b
  JOIN public.lessons l ON l.id=b.lesson_id
  JOIN public.courses c ON c.id=l.course_id
  WHERE b.id=p_textbook_id AND b.status='published' AND l.is_published AND c.is_published
    AND b.student_app_id=c.student_app_id
    AND ((l.content_scope='platform' AND l.tenant_id IS NULL) OR (l.content_scope='tenant' AND l.tenant_id=v_tenant))
    AND ((c.content_scope='platform' AND c.tenant_id IS NULL) OR (c.content_scope='tenant' AND c.tenant_id=v_tenant));
  IF NOT FOUND OR NOT private.current_user_can_read_student_app(v_app) THEN RETURN false; END IF;
  LOOP
    IF v_category IS NULL OR v_depth >= 8 OR v_category=ANY(v_seen) THEN RETURN false; END IF;
    SELECT c.parent_id INTO v_parent FROM public.course_categories c
    WHERE c.id=v_category AND c.is_published AND c.student_app_id=v_app
      AND ((c.content_scope='platform' AND c.tenant_id IS NULL) OR (c.content_scope='tenant' AND c.tenant_id=v_tenant));
    IF NOT FOUND THEN RETURN false; END IF;
    IF v_parent IS NULL THEN RETURN true; END IF;
    v_seen:=pg_catalog.array_append(v_seen,v_category); v_category:=v_parent; v_depth:=v_depth+1;
  END LOOP;
END;
$$;
ALTER FUNCTION private.can_read_published_textbook(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION private.can_read_published_textbook(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.can_read_published_textbook(uuid) TO authenticated;

CREATE FUNCTION private.can_read_published_teaching_module(p_module_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT auth.uid() IS NOT NULL AND EXISTS (
  SELECT 1 FROM public.digital_textbook_modules m
  JOIN public.digital_textbook_chapters c ON c.id=m.chapter_id
  JOIN public.digital_textbook_versions v ON v.id=c.version_id
  WHERE m.id=p_module_id AND c.status='published' AND v.status='published'
    AND private.can_read_published_textbook(v.textbook_id)
 );
$$;
ALTER FUNCTION private.can_read_published_teaching_module(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION private.can_read_published_teaching_module(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.can_read_published_teaching_module(uuid) TO authenticated;

-- Close ancestor catalog surfaces as well as modules, without removing manager access.
ALTER POLICY "authenticated read textbook catalog" ON public.digital_textbooks
 USING (public.current_user_can_manage_standard_question_bank() OR private.can_read_published_textbook(id));
ALTER POLICY "authenticated read textbook versions" ON public.digital_textbook_versions
 USING (public.current_user_can_manage_standard_question_bank() OR (status='published' AND private.can_read_published_textbook(textbook_id)));
ALTER POLICY "authenticated read textbook chapters" ON public.digital_textbook_chapters
 USING (public.current_user_can_manage_standard_question_bank() OR (status='published' AND EXISTS (
 SELECT 1 FROM public.digital_textbook_versions v WHERE v.id=version_id AND v.status='published' AND private.can_read_published_textbook(v.textbook_id))));
ALTER POLICY "authenticated read textbook modules" ON public.digital_textbook_modules
 USING (public.current_user_can_manage_standard_question_bank() OR private.can_read_published_teaching_module(id));
ALTER POLICY "authenticated read published learning agent lessons" ON public.learning_agent_lessons
 USING (status='published' AND private.can_read_published_teaching_module(module_id));
ALTER POLICY "authenticated read published learning agent script versions" ON public.learning_agent_script_versions
 USING (status='published' AND EXISTS (SELECT 1 FROM public.learning_agent_lessons l
 WHERE l.id=lesson_id AND l.status='published' AND private.can_read_published_teaching_module(l.module_id)));
DROP POLICY "authenticated read published learning agent script nodes" ON public.learning_agent_script_nodes;
-- The existing platform-owner ALL policy remains. Student raw SELECT returns zero rows.

-- Safe authored rows must be strings and reproduce the authoritative public narration.
-- Do not expose arbitrary nested keys, invalid segment payloads, or future configuration fields.
CREATE FUNCTION private.student_script_segments(p_script jsonb,p_segments jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
 SELECT coalesce(pg_catalog.jsonb_object_agg(e.key,e.value),'{}'::jsonb)
 FROM pg_catalog.jsonb_each(CASE WHEN pg_catalog.jsonb_typeof(p_segments)='object' THEN p_segments ELSE '{}'::jsonb END) e
 WHERE e.key IN ('zh-CN','ko-KR') AND CASE WHEN pg_catalog.jsonb_typeof(e.value)='array' THEN
   pg_catalog.jsonb_array_length(e.value)<=50
   AND NOT EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(e.value) s WHERE pg_catalog.jsonb_typeof(s)<>'string')
   AND pg_catalog.btrim((SELECT pg_catalog.string_agg(s.value,E'\n\n' ORDER BY s.ordinality) FROM pg_catalog.jsonb_array_elements_text(e.value) WITH ORDINALITY s),E' \n\r\t')
       =pg_catalog.btrim(coalesce(p_script->>e.key,p_script->>'zh-CN',''),E' \n\r\t')
 ELSE false END;
$$;
ALTER FUNCTION private.student_script_segments(jsonb,jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION private.student_script_segments(jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.student_script_segments(jsonb,jsonb) TO authenticated;

-- Owner-executed barrier view deliberately bypasses raw-table owner-only RLS.
-- Every row is explicitly checked against the caller's auth.uid/current active membership.
-- No caller-supplied user or tenant, no raw configuration column, no write grant.
CREATE VIEW public.student_learning_agent_script_nodes WITH (security_barrier=true) AS
 SELECT n.id,n.script_version_id,n.updated_at,n.sort_order,
   (SELECT coalesce(pg_catalog.jsonb_object_agg(e.key,e.value),'{}'::jsonb)
    FROM pg_catalog.jsonb_each(CASE WHEN pg_catalog.jsonb_typeof(n.teacher_script)='object' THEN n.teacher_script ELSE '{}'::jsonb END) e
    WHERE e.key IN ('zh-CN','ko-KR') AND pg_catalog.jsonb_typeof(e.value)='string') AS teacher_script,
   private.student_script_segments(n.teacher_script,n.configuration->'scriptSegments') AS segments,
   CASE WHEN n.configuration->'teacherVideo'->>'mode'='video' THEN 'video' ELSE 'legacy' END AS video_mode
 FROM public.learning_agent_script_nodes n
 JOIN public.learning_agent_script_versions v ON v.id=n.script_version_id
 JOIN public.learning_agent_lessons l ON l.id=v.lesson_id
 WHERE auth.uid() IS NOT NULL AND v.status='published' AND l.status='published'
   AND private.can_read_published_teaching_module(l.module_id);
ALTER VIEW public.student_learning_agent_script_nodes OWNER TO postgres;
REVOKE ALL ON public.student_learning_agent_script_nodes FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.student_learning_agent_script_nodes TO authenticated;
COMMENT ON VIEW public.student_learning_agent_script_nodes IS 'Caller-bound public narration only. Raw authoring configuration is never projected. StudentTeachingPolicy additionally verifies unlock, selection and revision.';
NOTIFY pgrst, 'reload schema';
COMMIT;

-- R3A: infrastructure maintenance only. Never resumes execution.
begin;

-- Bounded tenant sweep; terminal history does not occupy this index.
create index agent_runs_reconcile_deadline on public.agent_runs(tenant_id,deadline_at,id)
  where status in ('created','running','waiting_tool');

create function public.find_reconcilable_agent_runs_v1(p_tenant uuid,p_limit integer default 50)
returns table(run_id uuid,status text,deadline_at timestamptz,lease_expires_at timestamptz,
  cancel_requested_at timestamptz,state_version integer,fencing_token uuid)
language plpgsql security definer set search_path='' as $$
declare cutoff timestamptz:=clock_timestamp()-interval '6 seconds';
begin
  if p_tenant is null or p_limit is null or p_limit not between 1 and 100 then raise exception 'INVALID_REQUEST'; end if;
  return query select r.id,r.status,r.deadline_at,r.lease_expires_at,r.cancel_requested_at,r.state_version,r.fencing_token
    from public.agent_runs r where r.tenant_id=p_tenant and r.status in ('created','running','waiting_tool')
    and r.deadline_at <= cutoff
    order by r.deadline_at,r.id limit p_limit;
end $$;

create function public.reconcile_agent_run_v1(p_tenant uuid,p_run uuid,p_expected_version integer,p_fence uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.agent_runs; previous text; target text; reason text; stamp timestamptz; sequence bigint;
begin
  if p_tenant is null or p_run is null or p_expected_version is null or p_expected_version<1 or p_fence is null
    then raise exception 'INVALID_REQUEST'; end if;
  select * into r from public.agent_runs where tenant_id=p_tenant and id=p_run for update;
  if not found then return jsonb_build_object('result','not_found'); end if;
  -- Terminal winner is immutable, even if the scanner saw an older version/fence.
  if r.status in ('completed','failed','cancelled') then
    return jsonb_build_object('result','already_terminal','status',r.status);
  end if;
  if r.state_version<>p_expected_version or r.fencing_token<>p_fence then
    return jsonb_build_object('result','fence_conflict');
  end if;
  stamp:=clock_timestamp();
  -- Admission fixes lease=deadline; no heartbeat/ownership-death guess. Deadline
  -- already denies completion. Allow existing 3 x 2s stop-only cleanup first.
  if r.deadline_at>stamp-interval '6 seconds' then
    return jsonb_build_object('result','not_eligible','status',r.status);
  end if;
  previous:=r.status;
  if r.cancel_requested_at is not null and r.cancel_requested_at<r.deadline_at then
    target:='cancelled'; reason:='RUN_CANCELLED';
  else target:='failed'; reason:='DEADLINE_EXCEEDED'; end if;
  update public.agent_runs set status=target,state_version=state_version+1,ended_at=stamp,terminal_reason=reason
    where id=r.id and tenant_id=p_tenant and state_version=p_expected_version and fencing_token=p_fence;
  if not found then return jsonb_build_object('result','fence_conflict'); end if;
  select coalesce(max(seq),0) into sequence from public.agent_run_events where run_id=r.id;
  insert into public.agent_run_events(tenant_id,actor_id,run_id,seq,kind,metadata) values
    (r.tenant_id,r.actor_id,r.id,sequence+1,'run.reconciled',jsonb_build_object('reason',reason,'previousStatus',previous,
      'deadlineExceeded',true,'cancelRequested',r.cancel_requested_at is not null,'reconcilerVersion','deadline-terminal-v1')),
    (r.tenant_id,r.actor_id,r.id,sequence+2,'run.'||target,'{}'::jsonb);
  -- No message, usage, context, teaching data, or answer.final is written.
  return jsonb_build_object('result','reconciled','status',target,'reason',reason);
end $$;

create function public.reconcile_agent_run_batch_v1(p_tenant uuid,p_limit integer default 50)
returns jsonb language plpgsql security definer set search_path='' set lock_timeout='2s' as $$
declare candidate record; outcome jsonb; outcomes jsonb:='[]'; reconciled_cancelled integer:=0;
  reconciled_deadline_failed integer:=0;
begin
  -- A single bounded transaction. Any exception rolls back the entire batch;
  -- caller records a failed invocation, never reports a partial commit as success.
  for candidate in select * from public.find_reconcilable_agent_runs_v1(p_tenant,p_limit) loop
    outcome:=public.reconcile_agent_run_v1(p_tenant,candidate.run_id,candidate.state_version,candidate.fencing_token);
    outcomes:=outcomes||jsonb_build_array(jsonb_build_object('runId',candidate.run_id)||outcome);
    if outcome->>'result'='reconciled' then
      if outcome->>'status'='cancelled' then reconciled_cancelled:=reconciled_cancelled+1;
      else reconciled_deadline_failed:=reconciled_deadline_failed+1; end if;
    end if;
  end loop;
  return jsonb_build_object('contractVersion','deadline-terminal-v1','results',outcomes,
    'reconciledCancelled',reconciled_cancelled,'reconciledDeadlineFailed',reconciled_deadline_failed,'reconcileError',0);
end $$;

do $$ declare signature regprocedure; begin
  foreach signature in array array[
    'public.find_reconcilable_agent_runs_v1(uuid,integer)'::regprocedure,
    'public.reconcile_agent_run_v1(uuid,uuid,integer,uuid)'::regprocedure,
    'public.reconcile_agent_run_batch_v1(uuid,integer)'::regprocedure] loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',signature);
    execute format('grant execute on function %s to service_role',signature);
  end loop;
end $$;
commit;

-- Formal from-zero authoring. No policy changes, content seed or automatic publication.
BEGIN;

CREATE FUNCTION public.create_teaching_content_skeleton(
  p_lesson_id uuid,
  p_expected_updated_at timestamptz,
  p_chapter_title text,
  p_objectives text[] DEFAULT ARRAY[]::text[]
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE
  l public.lessons%rowtype;
  c public.courses%rowtype;
  profile_id uuid;
  app_slug text;
  textbook_id uuid;
  version_id uuid;
  chapter_id uuid;
  module_id uuid;
  teaching_lesson_id uuid;
BEGIN
  -- Match Script Studio's existing platform-owner contract, including provisioned accounts.
  IF auth.uid() IS NULL OR NOT coalesce(private.is_platform_owner(), false)
    OR EXISTS (SELECT 1 FROM public.tenant_provisioned_accounts WHERE user_id = auth.uid()) THEN
    RAISE EXCEPTION 'AUTHORING_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF p_chapter_title IS NULL OR length(btrim(p_chapter_title)) NOT BETWEEN 1 AND 120
    OR p_objectives IS NULL OR cardinality(p_objectives) > 6
    OR EXISTS (SELECT 1 FROM unnest(p_objectives) x WHERE x IS NULL OR length(btrim(x)) NOT BETWEEN 1 AND 400) THEN
    RAISE EXCEPTION 'AUTHORING_INVALID_INPUT' USING ERRCODE = '22023';
  END IF;

  -- Same lock order as existing authoring/publication triggers; serializes two HTTP sessions.
  PERFORM runtime_publish_private.authoring_lock();
  SELECT lesson.* INTO l FROM public.lessons lesson
    JOIN public.courses course ON course.id = lesson.course_id
    WHERE lesson.id = p_lesson_id FOR UPDATE OF lesson, course;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTHORING_RESOURCE_CHANGED' USING ERRCODE = 'PT409'; END IF;
  SELECT * INTO c FROM public.courses WHERE id = l.course_id;
  IF l.updated_at IS DISTINCT FROM p_expected_updated_at
    OR l.content_scope IS DISTINCT FROM c.content_scope
    OR l.tenant_id IS DISTINCT FROM c.tenant_id THEN
    RAISE EXCEPTION 'AUTHORING_RESOURCE_CHANGED' USING ERRCODE = 'PT409';
  END IF;
  -- App and profile are resolved here, never supplied by the browser.
  SELECT slug INTO app_slug FROM public.student_apps WHERE id = c.student_app_id AND slug = 'korean' FOR SHARE;
  IF app_slug IS NULL THEN RAISE EXCEPTION 'AUTHORING_UNSUPPORTED_APP' USING ERRCODE = '22023'; END IF;
  SELECT id INTO profile_id FROM public.learning_agent_profiles
    WHERE agent_code = 'uply-korean-teacher' AND subject_code = 'korean'
      AND access_feature = 'korean_course' AND status = 'published' FOR SHARE;
  IF profile_id IS NULL THEN RAISE EXCEPTION 'AUTHORING_PROFILE_UNAVAILABLE' USING ERRCODE = 'PT409'; END IF;

  -- Includes partial and archived legacy trees. Never overwrite or silently repair them.
  IF EXISTS (SELECT 1 FROM public.digital_textbooks WHERE lesson_id = l.id) THEN
    RAISE EXCEPTION 'AUTHORING_CONTENT_EXISTS' USING ERRCODE = 'PT409';
  END IF;
  INSERT INTO public.digital_textbooks (lesson_id, slug, level_code, title, student_app_id, agent_profile_id)
    VALUES (l.id, 'lesson-' || l.id::text, coalesce(nullif(c.level, ''), 'unspecified'),
      jsonb_build_object('zh-CN', l.title), c.student_app_id, profile_id) RETURNING id INTO textbook_id;
  INSERT INTO public.digital_textbook_versions (textbook_id, version_number)
    VALUES (textbook_id, 1) RETURNING id INTO version_id;
  -- Chapter zero is the existing preparation-chapter contract (no chapter test required).
  INSERT INTO public.digital_textbook_chapters (version_id, slug, chapter_number, title)
    VALUES (version_id, 'preparation', 0, jsonb_build_object('zh-CN', btrim(p_chapter_title))) RETURNING id INTO chapter_id;
  INSERT INTO public.digital_textbook_modules (chapter_id, module_code, sort_order, accent_role, title)
    VALUES (chapter_id, 'orientation', 1, 'jade', '{"zh-CN":"课前导航","ko-KR":"수업 안내"}') RETURNING id INTO module_id;
  INSERT INTO public.learning_agent_lessons (module_id, agent_profile_id, objectives)
    VALUES (module_id, profile_id, CASE WHEN cardinality(p_objectives) = 0 THEN '{}'::jsonb
      ELSE jsonb_build_object('zh-CN', to_jsonb(p_objectives)) END) RETURNING id INTO teaching_lesson_id;
  -- These existing skeleton tables have no actor columns. Script draft/node/publication
  -- audit remains in the existing actions with auth.uid(); no fabricated actor or script.
  RETURN jsonb_build_object('textbookId', textbook_id, 'versionId', version_id,
    'chapterId', chapter_id, 'moduleId', module_id, 'teachingLessonId', teaching_lesson_id,
    'profileId', profile_id, 'appSlug', app_slug, 'status', 'draft');
END;
$$;
REVOKE ALL ON FUNCTION public.create_teaching_content_skeleton(uuid, timestamptz, text, text[]) FROM PUBLIC, anon, service_role;
GRANT EXECUTE ON FUNCTION public.create_teaching_content_skeleton(uuid, timestamptz, text, text[]) TO authenticated;
COMMIT;

-- Canonical draft Activity binding. Additive function only; no content seeds.
BEGIN;
CREATE FUNCTION public.create_teaching_lesson_activity_binding(
  p_expected_freeze jsonb,
  p_private_answer jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $$
DECLARE
  approved constant jsonb := '{"lesson":"870d1e4c70d884294d31fa8da3cb62d5ecadb2d050b4056c03c9ce47525497c3","script":"dd808c0ed6d816809f0a527523473c1da4021f2ece369d82efa902312ed860a8","versionRow":"a26aabb7dec01619d475db395f8ba628aaf48ec0da3f41c553d518b34a9da158","nodes":["ad1d0d94e8c6c10daed7bd05daf1194f9b52300d8bdb87d3fa31e1a498a614b6","892dba849c29f16c336f199667942887992591fc5a6e3fda3fe21abe18262cd8","961b23a6e128744783793a15fb445c6611cbed7e9b94ccb5c6bab32d63229b71","28d7516c505956a7b50b52db44bf61e08839cb7e19d46ef0d23d982c412dc958","3b48b709e005413be9c9599fc428a464f33928655234da13e2751c36da505bb8","b1f9d770a40cb8096ef8df40a375afe15612f4add7c5882b1e8c91f8dd1d2c50","93b340135770be2aed8ded1fa3bb8310ded773f7799cd054d767fd8c29a7bd4e","0e5c8fc654af69801b2977dbc01252668368df6f92a2691f99cbb829fa36168b"],"parents":{"lessons":"5cc6c16a227f695e913acfabf930d26ee08febb20e2251881257a89e6bd99e53","digital_textbooks":"e5a83e4c6eae9a5467dc3b9bc0bc80661c2736f40f1966d72fa4371e6f64ee3c","digital_textbook_versions":"f6e179b2be3b045efcb440219180b33c6844ecd0044f22050504756b12646232","digital_textbook_chapters":"ab9580d2db8ca1bb91a3abcf595a213a78c5e0870f886d95505354a7485a4535","digital_textbook_modules":"85d9512d9a2eacb0d159f6e8b6baecbbffc6e7881f0bdf383fd7edea2d3e5d73","learning_agent_lessons":"1215200610900050bb5c0ac81ea8d7d6cb11e71e897a962a10ff4a35542de953"}}'::jsonb;
  lesson public.learning_agent_lessons%rowtype;
  module public.digital_textbook_modules%rowtype;
  chapter public.digital_textbook_chapters%rowtype;
  version public.digital_textbook_versions%rowtype;
  book public.digital_textbooks%rowtype;
  catalog public.lessons%rowtype;
  script public.learning_agent_script_versions%rowtype;
  n public.digital_textbook_nodes%rowtype;
  a public.digital_textbook_activities%rowtype;
  k public.digital_textbook_activity_secrets%rowtype;
  hashes jsonb;
  parents jsonb;
  inserted integer := 0;
  result text := 'EXISTING';
BEGIN
  IF auth.uid() IS NULL OR NOT coalesce(private.is_platform_owner(),false)
     OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='active')
     OR EXISTS(SELECT 1 FROM public.tenant_provisioned_accounts WHERE user_id=auth.uid()) THEN
    RAISE EXCEPTION 'AUTHORING_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF p_expected_freeze IS DISTINCT FROM approved THEN
    RAISE EXCEPTION 'AUTHORING_FREEZE_MISMATCH' USING ERRCODE='PT409';
  END IF;
  -- Private answer is supplied only by the authorized server workflow; never returned.
  IF p_private_answer IS NULL OR jsonb_typeof(p_private_answer) <> 'object'
     OR (p_private_answer - 'kind' - 'value') <> '{}'::jsonb
     OR p_private_answer->>'kind' IS DISTINCT FROM 'index'
     OR p_private_answer->'value' NOT IN ('0'::jsonb,'1'::jsonb,'2'::jsonb)
     OR NOT (p_private_answer ? 'value') THEN
    RAISE EXCEPTION 'AUTHORING_INVALID_PRIVATE_CONTRACT' USING ERRCODE='22023';
  END IF;
  PERFORM runtime_publish_private.authoring_lock();
  SELECT * INTO STRICT lesson FROM public.learning_agent_lessons l
    WHERE encode(sha256(convert_to(l.id::text,'UTF8')),'hex')=approved->>'lesson' FOR UPDATE;
  SELECT * INTO STRICT module FROM public.digital_textbook_modules WHERE id=lesson.module_id FOR UPDATE;
  SELECT * INTO STRICT chapter FROM public.digital_textbook_chapters WHERE id=module.chapter_id FOR UPDATE;
  SELECT * INTO STRICT version FROM public.digital_textbook_versions WHERE id=chapter.version_id FOR UPDATE;
  SELECT * INTO STRICT book FROM public.digital_textbooks WHERE id=version.textbook_id FOR UPDATE;
  SELECT * INTO STRICT catalog FROM public.lessons WHERE id=book.lesson_id FOR UPDATE;
  PERFORM 1 FROM public.courses WHERE id=catalog.course_id FOR SHARE;
  IF module.module_code<>'orientation' OR chapter.chapter_number<>0
    OR chapter.status<>'draft' OR version.status<>'draft' OR version.version_number<>1 OR book.status<>'draft'
    OR chapter.title->>'zh-CN' IS DISTINCT FROM '韩文字母入门'
    OR NOT EXISTS(SELECT 1 FROM public.courses c JOIN public.student_apps app ON app.id=c.student_app_id WHERE c.id=catalog.course_id AND app.slug='korean') THEN
    RAISE EXCEPTION 'AUTHORING_TARGET_MISMATCH' USING ERRCODE='PT409';
  END IF;
  IF (SELECT count(*) FROM public.learning_agent_script_versions WHERE lesson_id=lesson.id)<>1 THEN
    RAISE EXCEPTION 'AUTHORING_SCRIPT_COUNT' USING ERRCODE='PT409';
  END IF;
  SELECT * INTO STRICT script FROM public.learning_agent_script_versions WHERE lesson_id=lesson.id FOR UPDATE;
  IF script.version_number<>1 OR script.status<>'draft' OR script.published_at IS NOT NULL
     OR encode(sha256(convert_to(script.id::text,'UTF8')),'hex')<>approved->>'script'
     OR encode(sha256(convert_to(jsonb_build_array(to_jsonb(script))::text,'UTF8')),'hex')<>approved->>'versionRow' THEN
    RAISE EXCEPTION 'AUTHORING_SCRIPT_CHANGED' USING ERRCODE='PT409';
  END IF;
  PERFORM 1 FROM public.learning_agent_script_nodes WHERE script_version_id=script.id ORDER BY sort_order FOR UPDATE;
  SELECT jsonb_agg(encode(sha256(convert_to(to_jsonb(s)::text,'UTF8')),'hex') ORDER BY sort_order) INTO hashes
    FROM public.learning_agent_script_nodes s WHERE script_version_id=script.id;
  IF hashes IS DISTINCT FROM approved->'nodes' OR jsonb_array_length(hashes)<>8 THEN
    RAISE EXCEPTION 'AUTHORING_FROZEN_NODES_CHANGED' USING ERRCODE='PT409';
  END IF;
  parents := jsonb_build_object(
    'lessons',encode(sha256(convert_to(jsonb_build_array(to_jsonb(catalog))::text,'UTF8')),'hex'),
    'digital_textbooks',encode(sha256(convert_to(jsonb_build_array(to_jsonb(book))::text,'UTF8')),'hex'),
    'digital_textbook_versions',encode(sha256(convert_to(jsonb_build_array(to_jsonb(version))::text,'UTF8')),'hex'),
    'digital_textbook_chapters',encode(sha256(convert_to(jsonb_build_array(to_jsonb(chapter))::text,'UTF8')),'hex'),
    'digital_textbook_modules',encode(sha256(convert_to(jsonb_build_array(to_jsonb(module))::text,'UTF8')),'hex'),
    'learning_agent_lessons',encode(sha256(convert_to(jsonb_build_array(to_jsonb(lesson))::text,'UTF8')),'hex'));
  IF parents IS DISTINCT FROM approved->'parents' THEN
    RAISE EXCEPTION 'AUTHORING_PARENT_OR_OBJECTIVES_CHANGED' USING ERRCODE='PT409';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.digital_textbook_nodes WHERE module_id=module.id) THEN
    INSERT INTO public.digital_textbook_nodes(module_id,node_code,node_type,sort_order,estimated_minutes,title,content)
      VALUES(module.id,'hangul-introduction-vowel-recognition','practice',1,1,'{"zh-CN":"元音辨认"}','{}') RETURNING * INTO n;
    GET DIAGNOSTICS inserted = ROW_COUNT;
    IF inserted<>1 THEN RAISE EXCEPTION 'AUTHORING_NODE_COUNT'; END IF;
    INSERT INTO public.digital_textbook_activities(node_id,activity_key,activity_type,sort_order,prompt,instruction,options,public_config,max_attempts,counts_toward_completion)
      VALUES(n.id,'hangul-introduction-vowel-recognition','single_choice',1,'{"zh-CN":"哪个是元音？"}','{"zh-CN":"请选择一个选项。"}',
        '[{"zh-CN":"ㄱ"},{"zh-CN":"ㅏ"},{"zh-CN":"ㄴ"}]','{}',3,true) RETURNING * INTO a;
    GET DIAGNOSTICS inserted = ROW_COUNT;
    IF inserted<>1 THEN RAISE EXCEPTION 'AUTHORING_ACTIVITY_COUNT'; END IF;
    INSERT INTO public.digital_textbook_activity_secrets(activity_id,answer_key) VALUES(a.id,p_private_answer) RETURNING * INTO k;
    GET DIAGNOSTICS inserted = ROW_COUNT;
    IF inserted<>1 THEN RAISE EXCEPTION 'AUTHORING_SECRET_COUNT'; END IF;
    result := 'CREATED';
  END IF;
  -- Whole target must be exactly one complete binding. Never repair partial objects.
  IF (SELECT count(*) FROM public.digital_textbook_nodes WHERE module_id=module.id)<>1 THEN
    RAISE EXCEPTION 'AUTHORING_PARTIAL_OR_DUPLICATE' USING ERRCODE='PT409';
  END IF;
  SELECT * INTO STRICT n FROM public.digital_textbook_nodes WHERE module_id=module.id;
  IF (SELECT count(*) FROM public.digital_textbook_activities WHERE node_id=n.id)<>1 THEN
    RAISE EXCEPTION 'AUTHORING_PARTIAL_OR_DUPLICATE' USING ERRCODE='PT409';
  END IF;
  SELECT * INTO STRICT a FROM public.digital_textbook_activities WHERE node_id=n.id;
  SELECT * INTO STRICT k FROM public.digital_textbook_activity_secrets WHERE activity_id=a.id;
  IF n.node_code<>'hangul-introduction-vowel-recognition' OR n.node_type<>'practice' OR n.sort_order<>1 OR n.estimated_minutes<>1
     OR n.title<>'{"zh-CN":"元音辨认"}'::jsonb OR n.content<>'{}'::jsonb OR n.authoring_grammar_identities<>'[]'::jsonb
     OR a.activity_key<>'hangul-introduction-vowel-recognition' OR a.activity_type<>'single_choice' OR a.sort_order<>1
     OR a.prompt<>'{"zh-CN":"哪个是元音？"}'::jsonb OR a.instruction<>'{"zh-CN":"请选择一个选项。"}'::jsonb
     OR a.options<>'[{"zh-CN":"ㄱ"},{"zh-CN":"ㅏ"},{"zh-CN":"ㄴ"}]'::jsonb OR a.public_config<>'{}'::jsonb OR a.max_attempts<>3 OR NOT a.counts_toward_completion
     OR k.answer_key IS DISTINCT FROM p_private_answer OR k.explanation<>'{}'::jsonb OR k.transcript_ko IS NOT NULL OR k.audio_object_key IS NOT NULL OR k.audio_status<>'pending' THEN
    RAISE EXCEPTION 'AUTHORING_EXISTING_BINDING_MISMATCH' USING ERRCODE='PT409';
  END IF;
  RETURN jsonb_build_object('contract','canonical-activity-binding/1','result',result,
    'targetAlias','hangul-introduction','activityAlias','hangul-introduction-vowel-recognition',
    'operatorHash',encode(sha256(convert_to(auth.uid()::text,'UTF8')),'hex'),
    'nodeHash',encode(sha256(convert_to(n.id::text,'UTF8')),'hex'),
    'activityHash',encode(sha256(convert_to(a.id::text,'UTF8')),'hex'),
    'insertedRows',CASE WHEN result='CREATED' THEN 3 ELSE 0 END,
    'observedAt',clock_timestamp(),'transactionRef',pg_current_xact_id()::text);
END;
$$;
REVOKE ALL ON FUNCTION public.create_teaching_lesson_activity_binding(jsonb,jsonb) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.create_teaching_lesson_activity_binding(jsonb,jsonb) TO authenticated;
COMMIT;

-- Stage 0B. Source only; never apply to a shared/production DB as part of tests.
begin;
create schema agent_core_private;
revoke all on schema agent_core_private from public, anon, authenticated, service_role;

create table public.agent_definition_versions (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id),
  actor_id uuid not null references public.profiles(id), agent_code text not null, version text not null,
  status text not null check(status in ('published','disabled')), manifest jsonb not null check(jsonb_typeof(manifest)='object'),
  created_at timestamptz not null default clock_timestamp(), unique(tenant_id,agent_code,version), unique(tenant_id,id)
);
create table public.agent_conversations (
  id uuid primary key, tenant_id uuid not null references public.tenants(id), actor_id uuid not null references public.profiles(id),
  agent_code text not null, app_id text not null, scope_kind text not null, scope_ref text not null,
  status text not null default 'active' check(status in ('active','closed')),
  created_at timestamptz not null default clock_timestamp(), unique(tenant_id,actor_id,id)
);
create table public.agent_runs (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null, actor_id uuid not null,
  conversation_id uuid not null, input_message_id uuid not null, definition_id uuid not null,
  agent_code text not null, profile_version text not null, skill_ref jsonb not null,
  scope_ref text not null, status text not null default 'created' check(status in ('created','running','waiting_tool','completed','failed','cancelled')),
  idempotency_key text not null check(length(idempotency_key) between 8 and 128),
  request_digest text not null check(request_digest ~ '^[a-f0-9]{64}$'),
  budget jsonb not null, deadline_at timestamptz not null, lease_expires_at timestamptz not null,
  state_version integer not null default 1, fencing_token uuid not null default gen_random_uuid(), execution_attempt integer not null default 1,
  retry_of_run_id uuid, context_metadata jsonb not null default '{}', terminal_reason text,
  created_at timestamptz not null default clock_timestamp(), ended_at timestamptz,
  unique(tenant_id,actor_id,id), unique(tenant_id,actor_id,conversation_id,idempotency_key),
  foreign key(tenant_id,actor_id,conversation_id) references public.agent_conversations(tenant_id,actor_id,id),
  foreign key(tenant_id,definition_id) references public.agent_definition_versions(tenant_id,id),
  foreign key(tenant_id,actor_id,retry_of_run_id) references public.agent_runs(tenant_id,actor_id,id)
);
create unique index agent_runs_one_active on public.agent_runs(conversation_id) where status in ('created','running','waiting_tool');
create table public.agent_messages (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null, actor_id uuid not null,
  conversation_id uuid not null, run_id uuid not null, role text not null check(role in ('user','assistant')),
  content text not null check(length(content)<=100000), state text not null check(state in ('accepted','final','partial')),
  origin text not null default 'agent_core', source_refs jsonb not null default '[]',
  created_at timestamptz not null default clock_timestamp(), unique(run_id,role), unique(tenant_id,actor_id,id),
  foreign key(tenant_id,actor_id,conversation_id) references public.agent_conversations(tenant_id,actor_id,id),
  foreign key(tenant_id,actor_id,run_id) references public.agent_runs(tenant_id,actor_id,id) deferrable initially deferred
);
alter table public.agent_runs add constraint agent_runs_input_fk foreign key(tenant_id,actor_id,input_message_id)
  references public.agent_messages(tenant_id,actor_id,id) deferrable initially deferred;
create table public.agent_run_events (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null, actor_id uuid not null, run_id uuid not null,
  seq bigint not null, kind text not null, model_call_id uuid, tool_call_id text, skill_run_id uuid,
  metadata jsonb not null default '{}', created_at timestamptz not null default clock_timestamp(), unique(run_id,seq),
  foreign key(tenant_id,actor_id,run_id) references public.agent_runs(tenant_id,actor_id,id)
